"use client"
import { useRef } from "react"
import { Confetti, type ConfettiRef } from "@/components/ui/confetti"

export function Demo() {
  const effect = useRef<ConfettiRef>(null)
  return <div style={{ position: "relative", height: 320 }}>
    <button onClick={() => effect.current?.fire()}>Celebrate</button>
    <Confetti ref={effect} variant="stars" fullscreen />
  </div>
}
